const FIELDS={query:['query','queries','keyword','search term','từ khóa'],page:['page','pages','url','landing page'],clicks:['clicks','click'],impressions:['impressions','impression'],ctr:['ctr','click through rate'],position:['position','average position','avg position'],date:['date','day']};
export function parseCSV(text){
  text=text.replace(/^\uFEFF/,''); const first=(text.split(/\r?\n/,1)[0]||'');
  const candidates=[',',';','\t']; const delimiter=candidates.map(d=>[d,countOutside(first,d)]).sort((a,b)=>b[1]-a[1])[0][0];
  const rows=[]; let row=[],cell='',quote=false;
  for(let i=0;i<text.length;i++){const c=text[i]; if(quote){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quote=false;else cell+=c;}else if(c==='"')quote=true;else if(c===delimiter){row.push(cell);cell='';}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}
  if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);} if(quote) throw new Error('Unclosed quoted field');
  return {delimiter,rows:rows.filter(r=>r.some(x=>x.trim()))};
}
function countOutside(s,d){let q=false,n=0;for(let i=0;i<s.length;i++){if(s[i]==='"'){if(q&&s[i+1]==='"')i++;else q=!q;}else if(!q&&s[i]===d)n++;}return n;}
const key=s=>s.trim().toLowerCase().normalize('NFKC').replace(/[()%]/g,'').replace(/[_-]+/g,' ').replace(/\s+/g,' ');
export function mapHeaders(headers){const out={};headers.forEach((h,i)=>{const k=key(h);for(const [name,aliases] of Object.entries(FIELDS))if(aliases.includes(k))out[name]=i;});return out;}
function number(v,kind,delimiter,warnings){if(v==null||v.trim()==='')return null;const percent=/%\s*$/.test(v);if(percent&&kind!=='ctr')return null;let s=v.trim().replace(/[ \u00a0]/g,'').replace(/%$/,'');if(/^\d{1,3}([.,])\d{3}$/.test(s)){const sep=s.includes(',')?',':'.';if((delimiter===';'&&sep===',')||kind==='position'||kind==='ctr')s=s.replace(',','.');else{s=s.replace(/[.,]/g,'');warnings?.push(`Ambiguous numeric value ${v}; interpreted as thousands.`);}}else if(/^\d{1,3}(\.\d{3})+,\d+$/.test(s))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s))s=s.replace(/,/g,'');else if(s.includes(',')&&!s.includes('.'))s=s.replace(',','.');const n=Number(s);if(!Number.isFinite(n)||n<0||(['clicks','impressions'].includes(kind)&&!Number.isInteger(n)))return null;return kind==='ctr'&&n>1?n/100:n;}
export function normalizeUrl(value){try{const u=new URL(value.trim());if(!['http:','https:'].includes(u.protocol)||!u.hostname)return '';u.username='';u.password='';u.hash='';u.hostname=u.hostname.toLowerCase();if((u.protocol==='https:'&&u.port==='443')||(u.protocol==='http:'&&u.port==='80'))u.port='';u.pathname=u.pathname.replace(/\/{2,}/g,'/');if(u.pathname!=='/')u.pathname=u.pathname.replace(/\/$/,'');u.searchParams.sort();return u.href;}catch{return '';}}
function isoDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return '';const d=new Date(v+'T00:00:00Z');return Number.isFinite(d.valueOf())&&d.toISOString().slice(0,10)===v?v:'';}
const normQuery=v=>v.trim().normalize('NFKC').replace(/\s+/g,' ').toLocaleLowerCase();
export function ingest(text,engine,file='input.csv'){
 const {rows,delimiter}=parseCSV(text);if(rows.length<2)throw new Error('CSV has no data rows');if(rows.length>500001)throw new Error('CSV exceeds the 500,000 row safety limit');const map=mapHeaders(rows[0]);if(map.clicks==null||map.impressions==null)throw new Error('Required columns: Clicks and Impressions');if(map.query==null&&map.page==null)throw new Error('At least one dimension is required: Query or Page');
 const warnings=[];if(engine==='gsc'&&rows.length-1===1000)warnings.push('Exactly 1,000 rows: this may be a capped GSC UI export; conclusions may be incomplete.');if(map.query!=null&&map.page==null)warnings.push('Page dimension absent: query-page cannibalization cannot be assessed.');if(map.page!=null&&map.query==null)warnings.push('Query dimension absent: query opportunities cannot be assessed.');let rejected=0;const data=[];for(let i=1;i<rows.length;i++){const r=rows[i],clicks=number(r[map.clicks],'clicks',delimiter,warnings),impressions=number(r[map.impressions],'impressions',delimiter,warnings),position=number(r[map.position],'position',delimiter,warnings);if(clicks==null||impressions==null||clicks>impressions){rejected++;if(warnings.length<25)warnings.push(`Row ${i+1}: invalid clicks/impressions`);continue;}const query=map.query==null?'':normQuery(r[map.query]||''),rawPage=map.page==null?'':(r[map.page]||''),page=rawPage?normalizeUrl(rawPage):'',rawDate=map.date==null?'':(r[map.date]||'').trim(),date=isoDate(rawDate);if(rawPage&&!page){rejected++;if(warnings.length<25)warnings.push(`Row ${i+1}: invalid HTTP(S) page URL`);continue;}if(!query&&!page){rejected++;continue;}if(rawDate&&!date&&warnings.length<25)warnings.push(`Row ${i+1}: invalid ISO date`);data.push({engine,file,row:i+1,query,page,date,clicks,impressions,position,ctr:impressions?clicks/impressions:0});}
 for(let i=1;i<rows.length&&warnings.length<25;i++){const r=rows[i],rawPosition=map.position==null?'':(r[map.position]||'').trim(),rawCtr=map.ctr==null?'':(r[map.ctr]||'').trim();if(rawPosition&&number(rawPosition,'position',delimiter)==null)warnings.push(`Row ${i+1}: invalid position; other metrics retained`);if(rawCtr&&number(rawCtr,'ctr',delimiter)==null&&warnings.length<25)warnings.push(`Row ${i+1}: invalid CTR; recomputed CTR retained`);}if(map.date!=null){const dates=[...new Set(data.map(x=>x.date).filter(Boolean))].sort(),contiguous=dates.every((d,i)=>!i||(new Date(d)-new Date(dates[i-1])===86400000));if(!(dates.length>=14&&dates.length%2===0&&contiguous))warnings.push('Decay suppressed: requires at least 14 valid contiguous ISO dates split into equal periods.');}const finalWarnings=boundedWarnings(warnings);
 return {data,quality:{file,engine,delimiter,accepted:data.length,rejected,warnings:finalWarnings,dimensions:{query:map.query!=null,page:map.page!=null,date:map.date!=null}}};
}
const aggregate=(rows,keyFn)=>{const m=new Map();for(const r of rows){const k=keyFn(r);if(!k)continue;let a=m.get(k);if(!a){a={key:k,clicks:0,impressions:0,posNum:0,posDen:0,rows:0,engines:new Set(),sources:new Set()};m.set(k,a);}a.clicks+=r.clicks;a.impressions+=r.impressions;if(r.position!=null){a.posNum+=r.position*r.impressions;a.posDen+=r.impressions;}a.rows++;a.engines.add(r.engine);a.sources.add(`${r.file}:${r.row}`);}return [...m.values()].map(a=>({...a,ctr:a.impressions?a.clicks/a.impressions:0,position:a.posDen?a.posNum/a.posDen:null,engines:[...a.engines],sources:[...a.sources].slice(0,20)}));};
const score=(demand,position,confidence)=>Math.round(Math.min(100,(Math.log10(demand+1)*18+(position?Math.max(0,21-position)*2:0))*confidence));
function boundedWarnings(items,limit=25){const unique=[...new Set(items)],shown=unique.slice(0,limit);if(unique.length>limit)shown.push(`${unique.length-limit} additional distinct warnings omitted.`);return shown;}
export function analyze(rows){
 const groups=new Map();for(const r of rows){const k=[r.engine,r.query,r.page,r.date,r.clicks,r.impressions,r.position].join('\u0001'),a=groups.get(k)||[];a.push(r);groups.set(k,a);}const ambiguous=[...groups.values()].filter(a=>new Set(a.map(r=>r.file)).size>1);const blocked=new Set(ambiguous.flat());const unique=[...groups.values()].map(a=>a[0]).filter(r=>!blocked.has(r));const analysisWarnings=ambiguous.length?[`${ambiguous.length} observations repeated across differently scoped files were excluded because overlap cannot be resolved safely.`]:[];
 const opportunities=[];for(const engine of ['gsc','bing']){const e=unique.filter(r=>r.engine===engine);for(const a of aggregate(e,r=>`${r.query}\u0000${r.page}`)){if(a.impressions>=50&&a.position!=null&&a.position>=4&&a.position<=20){const confidence=Math.min(.85,.25+Math.log10(a.impressions+1)/6);opportunities.push(make('striking_distance',engine,a,score(a.impressions,a.position,confidence),confidence,`${engine.toUpperCase()} observed position ${a.position.toFixed(1)} with ${a.impressions} impressions.`));}}
  const qp=new Map();for(const r of e)if(r.query&&r.page){let a=qp.get(r.query);if(!a){a={pages:new Set(),rows:[]};qp.set(r.query,a);}a.pages.add(r.page);a.rows.push(r);}for(const [q,x] of qp)if(x.pages.size>1){const a=aggregate(x.rows,()=>q)[0];const confidence=Math.min(.8,.25+Math.log10(a.impressions+1)/7);opportunities.push(make('possible_cannibalization',engine,a,score(a.impressions,null,confidence),confidence,`${x.pages.size} URLs observed for this query; investigate intent/canonicals.`,{pages:[...x.pages].slice(0,10)}));}
 }
 const perEngine={};for(const engine of ['gsc','bing'])perEngine[engine]=new Map(aggregate(unique.filter(r=>r.engine===engine),r=>`${r.query}\u0000${r.page}`).map(x=>[x.key,x]));
 for(const engine of ['gsc','bing']){
  const dated=unique.filter(r=>r.engine===engine&&r.date),dates=[...new Set(dated.map(r=>r.date))].sort(),contiguous=dates.every((d,i)=>!i||(new Date(d)-new Date(dates[i-1])===86400000));
  if(dates.length>=14&&dates.length%2===0&&contiguous){
   const half=dates.length/2,cut=dates[half],coverage=new Map();
   for(const r of dated){const k=r.query+'\u0000'+r.page,entry=coverage.get(k)||{old:new Set(),recent:new Set()};entry[r.date<cut?'old':'recent'].add(r.date);coverage.set(k,entry);}
   const old=aggregate(dated.filter(r=>r.date<cut),r=>r.query+'\u0000'+r.page),recent=new Map(aggregate(dated.filter(r=>r.date>=cut),r=>r.query+'\u0000'+r.page).map(a=>[a.key,a]));
   for(const before of old){const after=recent.get(before.key);if(!after||before.impressions<50||after.impressions<1)continue;const days=coverage.get(before.key);if(!days||days.old.size!==half||days.recent.size!==half){analysisWarnings.push('Decay suppressed for '+before.key.replace('\u0000',' / ')+': incomplete per-key daily coverage.');continue;}const drop=before.clicks?1-after.clicks/before.clicks:0;if(drop>=.3){const confidence=Math.min(.78,.3+Math.log10(before.impressions+after.impressions+1)/8);opportunities.push({type:'period_decay',engine,query:before.key.split('\u0000')[0],page:before.key.split('\u0000')[1],score:score(before.impressions+after.impressions,after.position,confidence),evidenceConfidence:+confidence.toFixed(2),evidence:{periodBoundary:cut,daysPerPeriod:half,previous:metrics(before),recent:metrics(after),clickDrop:+drop.toFixed(3)},explanation:'Observed clicks fell '+Math.round(drop*100)+'% across equal contiguous complete periods; verify seasonality.',provenance:[...before.sources,...after.sources]});}}
  }else if(dates.length)analysisWarnings.push(engine.toUpperCase()+' decay suppressed: date range is not contiguous, even, and at least 14 days.');
 }
 for(const [k,g] of perEngine.gsc){const b=perEngine.bing.get(k);if(!b||g.position==null||b.position==null)continue;const go=g.position<=20,bo=b.position<=20;if(!go&&!bo)continue;const type=go&&bo?'cross_engine_consensus':'cross_engine_divergence',conservativePosition=Math.max(g.position,b.position),confidence=Math.min(.82,(type==='cross_engine_consensus'?.4:.25)+Math.log10(g.impressions+b.impressions+1)/8);opportunities.push({type,engine:'cross-engine',query:k.split('\u0000')[0],page:k.split('\u0000')[1],score:score(g.impressions+b.impressions,conservativePosition,confidence),evidenceConfidence:+confidence.toFixed(2),evidence:{scoringPosition:'weakest-engine',gsc:metrics(g),bing:metrics(b)},explanation:type.includes('consensus')?'Both engines independently show top-20 opportunity; score uses the weaker position. Metrics remain separate.':'Only one engine shows a top-20 opportunity; score uses the weaker position. Inspect intent and indexing.',provenance:[...g.sources,...b.sources]});}
 opportunities.sort((a,b)=>b.score-a.score);return {generatedAt:new Date().toISOString(),methodologyVersion:'0.4.0',analysisWarnings:boundedWarnings(analysisWarnings),observedTotals:{gsc:totals(unique.filter(r=>r.engine==='gsc')),bing:totals(unique.filter(r=>r.engine==='bing'))},opportunities};
}
function totals(rows){return {rows:rows.length,clicks:rows.reduce((s,r)=>s+r.clicks,0),impressions:rows.reduce((s,r)=>s+r.impressions,0)};}function metrics(a){return {clicks:a.clicks,impressions:a.impressions,ctr:+a.ctr.toFixed(4),position:a.position==null?null:+a.position.toFixed(2)};}function make(type,engine,a,s,c,ex,x={}){const [query,page='']=a.key.split('\u0000');return {type,engine,query,page,score:s,evidenceConfidence:+c.toFixed(2),evidence:{[engine]:metrics(a),...x},explanation:ex,provenance:a.sources};}
export function safeCell(v){const s=String(v??'').replace(/^\uFEFF/,'');return /^[\s]*[=+\-@]/.test(s)||/[\n\r\t]/.test(s)?`'${s}`:s;}
export function toCSV(report){const h=['score','evidence_confidence','type','engine','query','page','explanation','evidence_json','provenance'];return [h,...report.opportunities.map(o=>[o.score,o.evidenceConfidence,o.type,o.engine,o.query,o.page,o.explanation,JSON.stringify(o.evidence),o.provenance.join('|')])].map(r=>r.map(v=>`"${safeCell(v).replace(/"/g,'""')}"`).join(',')).join('\r\n');}
const md=v=>String(v??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/[<>]/g,c=>c==='<'?'&lt;':'&gt;').replace(/\|/g,'\\|');
export function toMarkdown(report){return `# OpenSEO Evidence backlog\n\nGenerated locally: ${md(report.generatedAt)}\n\n|Score|Evidence confidence|Engine|Type|Query / page|Evidence and provenance|\n|---:|---:|---|---|---|---|\n${report.opportunities.map(o=>`|${o.score}|${o.evidenceConfidence}|${md(o.engine)}|${md(o.type)}|${md(o.query||o.page)}|${md(o.explanation)} Evidence: ${md(JSON.stringify(o.evidence))}. Sources: ${md(o.provenance.join(', '))}|`).join('\n')}\n`;}
